#!/bin/bash
# Production E2E v5: desktop + mobile + playback on https://mq1.vercel.app
set -u
cd /home/z/my-project
URL="https://mq1.vercel.app"
export AGENT_BROWSER_SESSION="mq-prod-e2e-v5"

echo "=== DESKTOP 1440x900 ==="
agent-browser set viewport 1440 900 >/dev/null
agent-browser open "$URL" >/dev/null
agent-browser wait 4000
echo "-- console errors:"
agent-browser console 2>/dev/null | grep -iE "error" | grep -viE "deprecat|DevTools|favicon|third-party|Autofill|404|net::" | head -5 || echo "  (none)"
agent-browser eval "(() => {   const raw = localStorage.getItem('mq-store-v8');   const ok = raw && JSON.parse(raw).state?.playlists?.length === 3;   if (!ok) {     localStorage.setItem('mq-store-v8', JSON.parse(atob('')));     location.assign('/'); return 'injected+navigating'; } return 'store present'; })()"
agent-browser open "$URL" >/dev/null
agent-browser wait 3500
agent-browser eval "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Демо-режим'); if (!b) return 'NO DEMO BTN'; b.click(); return 'demo clicked'; })()"
agent-browser wait 4500
agent-browser eval "(() => { const s = document.querySelector('section[aria-label=\"Плейлисты\"]'); return s ? 'SECTION OK playlists=' + (JSON.parse(localStorage.getItem('mq-store-v8')).state.playlists.length) : 'NO SECTION'; })()"
agent-browser eval "(() => { const sec = document.querySelector('section[aria-label=\"Плейлисты\"]'); const y = window.scrollY + sec.getBoundingClientRect().top - 55; window.scrollTo(0, y); return 'scrolled'; })()"
agent-browser wait 1500
echo "-- desktop telemetry:"
agent-browser eval "(() => { const sec = document.querySelector('section[aria-label=\"Плейлисты\"]'); const r = sec.getBoundingClientRect(); const hero = sec.querySelector('[role=button]'); const hr = hero.getBoundingClientRect(); const strips = [...sec.querySelectorAll('[role=button]')].slice(1, 4).map(e => e.getBoundingClientRect()); const hosts = [...sec.querySelectorAll('div')].filter(d => d.className && String(d.className).includes('overflow-hidden') && d.getAttribute('aria-hidden') === 'true'); const bh = hosts.length ? hosts[hosts.length-1].getBoundingClientRect() : null; const svg = sec.querySelector('svg'); const vtitle = hero.querySelector('p[title]'); const vcs = vtitle ? getComputedStyle(vtitle) : null; return JSON.stringify({sec: {top: +r.top.toFixed(1), h: +r.height.toFixed(1)}, hero: {x: +hr.left.toFixed(1), y: +hr.top.toFixed(1), w: +hr.width.toFixed(1), h: +hr.height.toFixed(1)}, strip1: {w: +strips[0].width.toFixed(1), h: +strips[0].height.toFixed(1)}, band: bh ? {y: +bh.top.toFixed(1), h: +bh.height.toFixed(1), w: +bh.width.toFixed(1)} : null, chromeSvg: !!svg, svgPaths: svg ? svg.querySelectorAll('path').length : 0, vtitleFont: vcs ? vcs.fontSize : null, overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, brokenImgs: [...document.images].filter(i => i.complete && i.naturalWidth === 0).length}); })()"
agent-browser screenshot "download/playlist-ref-qa/prod-desktop-v5.png"
echo "-- desktop shot saved"
echo "-- playback test:"
agent-browser eval "(() => { const hero = document.querySelector('section[aria-label=\"Плейлисты\"] [role=button]'); const btn = hero.querySelector('button'); if (!btn) return 'NO PLAY BTN'; btn.click(); return 'play clicked'; })()"
agent-browser wait 2500
agent-browser eval "(() => { const s = JSON.parse(localStorage.getItem('mq-store-v8')||'{}'); return JSON.stringify({queueLen: s.state?.queue?.length, currentTrack: s.state?.currentTrack?.title || null}); })()"

echo "=== MOBILE 390x844 ==="
agent-browser set viewport 390 844 >/dev/null
agent-browser wait 800
agent-browser open "$URL" >/dev/null
agent-browser wait 3500
agent-browser eval "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Демо-режим'); if (b) b.click(); return b ? 'demo' : 'no-demo-btn'; })()"
agent-browser wait 4000
agent-browser eval "(() => { const sec = document.querySelector('section[aria-label=\"Плейлисты\"]'); if (!sec) return 'NO SECTION'; const bh = [...sec.querySelectorAll('div')].find(d => (d.getAttribute('style')||'').includes('height: 110px')); if (!bh) return 'NO BAND'; const r = bh.getBoundingClientRect(); window.scrollTo(0, Math.max(0, window.scrollY + r.top + r.height - 844 + 36)); return 'scrolled'; })()"
agent-browser wait 1400
agent-browser eval "(() => { const sec = document.querySelector('section[aria-label=\"Плейлисты\"]'); const bh = [...sec.querySelectorAll('div')].find(d => (d.getAttribute('style')||'').includes('height: 110px')); const r = bh.getBoundingClientRect(); window.scrollTo(0, Math.max(0, window.scrollY + r.top + r.height - 844 + 36)); return 're-scrolled'; })()"
agent-browser wait 900
echo "-- mobile telemetry:"
agent-browser eval "(() => { const sec = document.querySelector('section[aria-label=\"Плейлисты\"]'); const bh = [...sec.querySelectorAll('div')].find(d => (d.getAttribute('style')||'').includes('height: 110px')); const r = bh ? bh.getBoundingClientRect() : null; const svg = sec.querySelector('svg'); const playBtns = [...sec.querySelectorAll('button')].map(b => Math.round(b.getBoundingClientRect().width)).filter(s => s > 20).slice(0, 6); const titles = [...sec.querySelectorAll('p[title]')].slice(0, 4).map(t => ({t: (t.title||'').slice(0, 10), clipped: t.scrollWidth > t.clientWidth + 1})); return JSON.stringify({band: r ? {y: +r.top.toFixed(1), h: +r.height.toFixed(1)} : null, chromeSvg: !!svg, overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth, hscroll: document.documentElement.scrollWidth > document.documentElement.clientWidth, broken: [...document.images].filter(i => i.complete && i.naturalWidth === 0).length, playBtnSizes: playBtns, titles}); })()"
agent-browser screenshot "download/playlist-ref-qa/prod-mobile-v5.png"
echo "-- mobile shot saved"
